package com.volna.inventory_service.controller;import com.volna.inventory_service.dto.inventory.*;import com.volna.inventory_service.enums.InventoryStatus;import com.volna.inventory_service.security.AuthenticatedUser;import com.volna.inventory_service.service.InventoryItemService;import jakarta.validation.Valid;import com.volna.inventory_service.exception.BadRequestException;import org.springframework.data.domain.*;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/inventory/items") public class InventoryItemController{private final InventoryItemService s;public InventoryItemController(InventoryItemService s){this.s=s;}@GetMapping public Page<InventoryItemResponse> all(@AuthenticationPrincipal AuthenticatedUser u,@RequestParam(required=false)String search,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){if(page<0||size<1||size>100)throw new BadRequestException("page must be >= 0 and size must be between 1 and 100");return s.getAll(u.authUserId(),search,PageRequest.of(page,size));}@GetMapping("/low-stock")public Object low(@AuthenticationPrincipal AuthenticatedUser u){return s.byStatus(u.authUserId(),InventoryStatus.LOW_STOCK);}@GetMapping("/out-of-stock")public Object out(@AuthenticationPrincipal AuthenticatedUser u){return s.byStatus(u.authUserId(),InventoryStatus.OUT_OF_STOCK);}@GetMapping("/{id}")public InventoryItemResponse get(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable Long id){return s.get(u.authUserId(),id);}@PostMapping public ResponseEntity<InventoryItemResponse> create(@AuthenticationPrincipal AuthenticatedUser u,@Valid @RequestBody CreateInventoryItemRequest q){return ResponseEntity.status(HttpStatus.CREATED).body(s.create(u.authUserId(),q));}@PutMapping("/{id}")public InventoryItemResponse update(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable Long id,@Valid @RequestBody UpdateInventoryItemRequest q){return s.update(u.authUserId(),id,q);}@DeleteMapping("/{id}")public ResponseEntity<Void> delete(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable Long id){s.delete(u.authUserId(),id);return ResponseEntity.noContent().build();}@PatchMapping("/{id}/stock")public InventoryItemResponse stock(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable Long id,@Valid @RequestBody StockAdjustmentRequest q){return s.adjust(u.authUserId(),id,q);}}
